using System.Buffers.Binary;

namespace Starlings.Models.Whisper.Tests;

/// <summary>Log-mel spectrogram parity against transformers WhisperFeatureExtractor (numpy path).</summary>
/// <remarks>Golden data is generated by reference (see scratch), not committed; tests load it when present.</remarks>
public sealed class MelSpectrogramParityTests
{
    private const string Golden = "/home/mark/Projects/starling/.models/snapshots/whisper-large-v3-turbo";

    private static double[] ReadF64(string path) => Read<double>(path, sizeof(double), reader => reader.ReadDouble());

    private static float[] ReadF32(string path) => Read<float>(path, sizeof(float), reader => reader.ReadSingle());

    private static T[] Read<T>(string path, int size, Func<BinaryReader, T> read)
    {
        byte[] bytes = File.ReadAllBytes(path);
        var result = new T[bytes.Length / size];
        using var ms = new MemoryStream(bytes);
        using var reader = new BinaryReader(ms);
        for (int i = 0; i < result.Length; i++)
        {
            result[i] = read(reader);
        }

        return result;
    }

    [Fact]
    public void HannWindowMatchesReference()
    {
        double[] expected = ReadF64($"{Golden}/golden-window.f64");
        double[] actual = WhisperMelSpectrogram.ComputeHannWindow();
        Assert.Equal(expected.Length, actual.Length);
        for (int i = 0; i < expected.Length; i++)
        {
            Assert.True(Math.Abs(expected[i] - actual[i]) < 1e-12, $"window[{i}] expected {expected[i]} actual {actual[i]}");
        }
    }

    [Fact]
    public void MelFilterBankMatchesReference()
    {
        double[] expected = ReadF64($"{Golden}/golden-mel-filters.f64");
        double[,] actual = WhisperMelSpectrogram.ComputeMelFilters();
        for (int k = 0; k < WhisperMelSpectrogram.NumFrequencyBins; k++)
        {
            for (int m = 0; m < WhisperMelSpectrogram.NumMelBins; m++)
            {
                double e = expected[k * WhisperMelSpectrogram.NumMelBins + m];
                Assert.True(Math.Abs(e - actual[k, m]) < 1e-8, $"filter[{k},{m}] expected {e} actual {actual[k, m]}");
            }
        }
    }

    [Fact]
    public void MelMatchesReference()
    {
        double[] waveform = ReadF64($"{Golden}/golden-waveform.f64");
        float[] expected = ReadF32($"{Golden}/golden-mel-numpy.f32");
        float[] actual = WhisperMelSpectrogram.Extract(waveform);

        Assert.Equal(expected.Length, actual.Length);
        float maxAbs = 0f;
        int arg = -1;
        for (int i = 0; i < expected.Length; i++)
        {
            float d = Math.Abs(expected[i] - actual[i]);
            if (d > maxAbs)
            {
                maxAbs = d;
                arg = i;
            }
        }

        Assert.True(maxAbs < 1e-6, $"max abs diff {maxAbs} at index {arg} (expected {expected[arg]}, actual {actual[arg]})");
    }
}
